INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(5725, 'plPL', 'Moc niszczenia...', 'Jak zapewne wiesz, wielu mieszkańców Legionu obdarowuje swoich wyznawców. Niektóre z tych darów, zdaniem Mrocznej Pani, lepiej przysłużyłyby się w jej rękach niż w rękach tych o... węższych horyzontach.$B$BDoskonałym przykładem jest odłam Rady Cieni ukryty w jaskiniach pod Orgrimmarem, znany jako Palące Ostrze. Pani mówi mi, że członkowie Palącego Ostrza weszli w posiadanie dwóch potężnych ksiąg zaklęć – chciałaby je od nich „pożyczyć”. Zdobędziesz je dla niej.', 'Przynieś księgi „Zaklęcia cienia” i „Inkantacje z Otchłani” Varimathrasowi w Podmieście.', '', 'Wróć do Varimathrasa nad Jeziorem Lordamere w Srebrzystym Borze.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(5725, 'plPL', 'Dobrze, $N. $GDobrze przysłużyłeś:Dobrze przysłużyłaś; się Mrocznej Pani. Twoja wytrwałość i ambicja bardzo się przydadzą poddanym Pani. Wróć do mnie w przyszłości. Być może będę mieć dla ciebie inne zadania, które pomogą Mrocznej Pani w jej dążeniach, by pokonać Króla Lisza i całkowicie wyzwolić Plagę.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(5725, 'plPL', 'Czeka na mnie setka innych spraw, $N. Masz te księgi?', 0);
